import os
from datetime import datetime, timezone
from typing import Any, Dict, List, Optional

import boto3


def _to_epoch_millis(value: Any) -> int:
    if isinstance(value, (int, float)):
        return int(value)
    if isinstance(value, datetime):
        dt = value if value.tzinfo else value.replace(tzinfo=timezone.utc)
        return int(dt.timestamp() * 1000)
    if isinstance(value, str):
        s = value.strip()
        if s.endswith("Z"):
            s = s[:-1] + "+00:00"
        dt = datetime.fromisoformat(s)
        if dt.tzinfo is None:
            dt = dt.replace(tzinfo=timezone.utc)
        return int(dt.timestamp() * 1000)
    raise TypeError("time values must be epoch millis, datetime, or ISO-8601 string")


def _escape_logs_insights_string(value: str) -> str:
    return value.replace("\\", "\\\\").replace('"', '\\"')


def _build_filter_expression(field_filters: Optional[Dict[str, Any]]) -> str:
    if not field_filters:
        return ""
    parts = []
    for field, value in field_filters.items():
        field_ref = field if field.startswith("@") else field
        if isinstance(value, str):
            parts.append(f'{field_ref} = "{_escape_logs_insights_string(value)}"')
        elif isinstance(value, bool):
            parts.append(f"{field_ref} = {'true' if value else 'false'}")
        elif value is None:
            parts.append(f"isblank({field_ref})")
        else:
            parts.append(f"{field_ref} = {value}")
    return " and ".join(parts)


def query_recent_logs(
    log_group_names: List[str],
    start_time: Any,
    end_time: Any,
    field_filters: Optional[Dict[str, Any]] = None,
    limit: int = 100,
    region_name: Optional[str] = None,
) -> List[Dict[str, Any]]:
    client = boto3.client("logs", region_name=region_name or os.getenv("AWS_REGION") or os.getenv("AWS_DEFAULT_REGION"))

    start_ms = _to_epoch_millis(start_time)
    end_ms = _to_epoch_millis(end_time)

    filter_expr = _build_filter_expression(field_filters)
    query_lines = [
        "fields @timestamp, @message, @logStream, @log",
    ]
    if filter_expr:
        query_lines.append(f"| filter {filter_expr}")
    query_lines.extend(
        [
            "| sort @timestamp desc",
            f"| limit {int(limit)}",
        ]
    )
    query_string = "\n".join(query_lines)

    response = client.start_query(
        logGroupNames=log_group_names,
        startTime=start_ms // 1000,
        endTime=end_ms // 1000,
        queryString=query_string,
        limit=int(limit),
    )
    query_id = response["queryId"]

    while True:
        result = client.get_query_results(queryId=query_id)
        status = result["status"]
        if status in {"Complete", "Failed", "Cancelled", "Timeout", "Unknown"}:
            break

    if status != "Complete":
        raise RuntimeError(f"CloudWatch Logs query did not complete successfully: {status}")

    normalized: List[Dict[str, Any]] = []
    for row in result.get("results", []):
        item: Dict[str, Any] = {}
        for cell in row:
            field = cell.get("field")
            value = cell.get("value")
            item[field] = value
        normalized.append(item)

    return normalized
